// Islamic quiz question bank (generated by scripts/convert-quiz.mjs).
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

export const QUIZ_CATEGORIES = [
  "quran",
  "messenger",
  "caliphs",
  "sahaba",
  "prophets",
  "fiqh",
  "aqeedah",
  "hadith",
] as const;
export type QuizCategoryId = (typeof QUIZ_CATEGORIES)[number];

/** q = question, c = choices, a = index of the answer in c, e = explanation, s = source. */
export type QuizQuestion = { q: string; c: string[]; a: number; e?: string; s?: string };
export type QuizBank = { id: QuizCategoryId; questions: QuizQuestion[] }[];

export const getQuizBank = cache(async (): Promise<QuizBank> =>
  JSON.parse(await fs.readFile(path.join(process.cwd(), "data/quiz/questions.json"), "utf8")),
);
